import{_ as r,o as e,c as t,a2 as o}from"./chunks/framework.DzTVEUQW.js";const u=JSON.parse('{"title":"术语词典","description":"","frontmatter":{},"headers":[],"relativePath":"glossary.md","filePath":"glossary.md","lastUpdated":null}'),h={name:"glossary.md"};function n(i,a,l,s,p,d){return e(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="术语词典" tabindex="-1">术语词典 <a class="header-anchor" href="#术语词典" aria-label="Permalink to &quot;术语词典&quot;">​</a></h1><blockquote><p>系列里用到的修仙黑话，都在这查。</p></blockquote><h2 id="核心概念" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念" aria-label="Permalink to &quot;核心概念&quot;">​</a></h2><h3 id="灵气" tabindex="-1">灵气 <a class="header-anchor" href="#灵气" aria-label="Permalink to &quot;灵气&quot;">​</a></h3><p><strong>对应：</strong> 代码、编程能力</p><p>程序员的根本能量。写代码就是修炼灵气，灵气越深厚，能解决的问题越复杂。</p><hr><h3 id="功法" tabindex="-1">功法 <a class="header-anchor" href="#功法" aria-label="Permalink to &quot;功法&quot;">​</a></h3><p><strong>对应：</strong> 编程语言</p><p>不同的编程语言就是不同的功法路线。C语言是上古功法，威力大但修炼难度高；Python是速成功法，入门快但深度有限；Java是名门正派功法，体系完整规矩多。选择功法决定了你的修炼方向。</p><hr><h3 id="法器" tabindex="-1">法器 <a class="header-anchor" href="#法器" aria-label="Permalink to &quot;法器&quot;">​</a></h3><p><strong>对应：</strong> 数据结构</p><p>程序操作数据的工具。数组、链表、树、图、哈希表——每种数据结构都是一种法器，有不同的威力和适用场景。选错法器（数据结构）会导致程序效率低下，就像修士用错法器打不赢对手。</p><hr><h3 id="丹药-筑基丹" tabindex="-1">丹药 / 筑基丹 <a class="header-anchor" href="#丹药-筑基丹" aria-label="Permalink to &quot;丹药 / 筑基丹&quot;">​</a></h3><p><strong>对应：</strong> 学习资源</p><p>帮助突破境界的经典教材和课程。《CSAPP》是筑基丹，《算法导论》是凝气丹，MIT 6.006是辅助修炼的丹方。</p><hr><h2 id="体系架构" tabindex="-1">体系架构 <a class="header-anchor" href="#体系架构" aria-label="Permalink to &quot;体系架构&quot;">​</a></h2><h3 id="天道规则" tabindex="-1">天道规则 <a class="header-anchor" href="#天道规则" aria-label="Permalink to &quot;天道规则&quot;">​</a></h3><p><strong>对应：</strong> 操作系统内核</p><p>所有程序运行的基本法则。进程调度、内存管理、文件系统、IO——这些是操作系统定的规则，不管你写什么代码都在这套规则里活动。就像修仙世界的天道，无法违抗，只能顺应。</p><hr><h3 id="天地法则" tabindex="-1">天地法则 <a class="header-anchor" href="#天地法则" aria-label="Permalink to &quot;天地法则&quot;">​</a></h3><p><strong>对应：</strong> CPU指令集架构</p><p>x86/ARM/RISC-V——硬件世界的根本法则。比天道规则（操作系统）更底层，是所有软件最终必须遵守的物理法则。操作系统都跑在指令集之上。</p><hr><h3 id="传送阵" tabindex="-1">传送阵 <a class="header-anchor" href="#传送阵" aria-label="Permalink to &quot;传送阵&quot;">​</a></h3><p><strong>对应：</strong> 计算机网络</p><p>连接不同系统的通道。TCP/IP、HTTP——网络协议就是修仙世界的传送阵，让你的程序能跟远端通信。不懂网络，你写的每个接口都是孤岛。</p><hr><h2 id="修炼状态" tabindex="-1">修炼状态 <a class="header-anchor" href="#修炼状态" aria-label="Permalink to &quot;修炼状态&quot;">​</a></h2><h3 id="境界" tabindex="-1">境界 <a class="header-anchor" href="#境界" aria-label="Permalink to &quot;境界&quot;">​</a></h3><p><strong>对应：</strong> 技术认知层次</p><p>炼气→筑基→金丹→元婴→化神→渡劫。每个境界代表一个技术认知层次，不是工作年限，而是对计算机系统的理解深度。</p><hr><h3 id="渡劫" tabindex="-1">渡劫 <a class="header-anchor" href="#渡劫" aria-label="Permalink to &quot;渡劫&quot;">​</a></h3><p><strong>对应：</strong> 技术认知跃迁</p><p>从会用到理解到创造的关键突破。炼气到筑基是渡劫（从写代码到懂原理），金丹到元婴是渡劫（从软件到硬件）。每次渡劫都是认知的质变，不是知识的堆叠。</p><hr><h3 id="走火入魔" tabindex="-1">走火入魔 <a class="header-anchor" href="#走火入魔" aria-label="Permalink to &quot;走火入魔&quot;">​</a></h3><p><strong>对应：</strong> 技术选型失误、架构设计错误</p><p>选错技术栈、架构设计不当，导致系统失控。就像修士练功走偏，轻则效率低下，重则系统崩溃。</p><hr><h3 id="心魔" tabindex="-1">心魔 <a class="header-anchor" href="#心魔" aria-label="Permalink to &quot;心魔&quot;">​</a></h3><p><strong>对应：</strong> 不懂数据结构滥用框架</p><p>表面能跑，底层不稳。不懂数据结构就用各种框架，短期没问题，长期遇到性能瓶颈就束手无策。这是码农最常见的心魔。</p><hr><h2 id="社会关系" tabindex="-1">社会关系 <a class="header-anchor" href="#社会关系" aria-label="Permalink to &quot;社会关系&quot;">​</a></h2><h3 id="宗门" tabindex="-1">宗门 <a class="header-anchor" href="#宗门" aria-label="Permalink to &quot;宗门&quot;">​</a></h3><p><strong>对应：</strong> 技术社区/开源项目</p><p>Linux社区、Apache基金会、CNCF——这些是码农的宗门。加入宗门（参与开源）可以获得修炼资源和同道切磋，也是提升修为的重要途径。</p><hr><h3 id="秘境" tabindex="-1">秘境 <a class="header-anchor" href="#秘境" aria-label="Permalink to &quot;秘境&quot;">​</a></h3><p><strong>对应：</strong> 经典论文/源码精读</p><p>Linux内核源码、TCP RFC、数据库论文——这些是码农的秘境。深入秘境探险（源码精读），可以获得常人难以获得的修炼感悟。</p><hr><h3 id="飞升" tabindex="-1">飞升 <a class="header-anchor" href="#飞升" aria-label="Permalink to &quot;飞升&quot;">​</a></h3><p><strong>对应：</strong> 创造改变行业的技术</p><p>图灵奖级别的贡献。创造的技术或理念改变了整个行业的走向。Linus创造Linux和Git，Dennis Ritchie创造C语言和Unix——这都是飞升。</p><hr><h2 id="散人" tabindex="-1">散人 <a class="header-anchor" href="#散人" aria-label="Permalink to &quot;散人&quot;">​</a></h2><p><strong>对应：</strong> 独立开发者/自由创作者</p><p>不入宗门、不受束缚的修士。不依附于某个大厂或机构，凭本事独立行走江湖。玄芯散人即为独立修行的散人。</p>',65)])])}const b=r(h,[["render",n]]);export{u as __pageData,b as default};
